using EduCenterManagement.Data; using EduCenterManagement.Enums; using EduCenterManagement.ViewModels.ParentChildren; using Microsoft.EntityFrameworkCore;
namespace EduCenterManagement.Repositories;
public sealed class ParentChildCommentsRepository(ApplicationDbContext db) : IParentChildCommentsRepository { public async Task<CommentsPageViewModel?> GetCommentsAsync(int parentProfileId,int studentId,int? classId,int page,int pageSize,CancellationToken ct=default) { if(!await db.ParentStudentLinks.AsNoTracking().AnyAsync(x=>x.ParentId==parentProfileId&&x.StudentId==studentId&&x.Status==ParentStudentLinkStatus.Accepted,ct)) return null; var classes=await db.Enrollments.AsNoTracking().Where(x=>x.StudentId==studentId&&x.Status==EnrollmentStatus.Confirmed).Select(x=>new AttendanceClassOptionViewModel{Id=x.ClassId,Name=x.Class.Name}).ToListAsync(ct); if(classId.HasValue&&!classes.Any(x=>x.Id==classId.Value))return null; var q=db.TeacherComments.AsNoTracking().Where(x=>x.StudentId==studentId&&x.Visibility=="parent_student");if(classId.HasValue)q=q.Where(x=>x.ClassId==classId.Value);var total=await q.CountAsync(ct);var items=await q.OrderByDescending(x=>x.CreatedAt).Skip((page-1)*pageSize).Take(pageSize).Select(x=>new ParentCommentRowViewModel{TeacherName=x.Teacher.FullName,SubjectName=x.Class.Subject.Name,ClassName=x.Class.Name,SessionNumber=x.Session==null?null:x.Session.SessionNumber,Rating=x.Rating,Content=x.Content,CreatedAt=x.CreatedAt}).ToListAsync(ct);var student=await db.StudentProfiles.AsNoTracking().SingleAsync(x=>x.Id==studentId,ct);return new(){StudentId=studentId,StudentName=student.FullName,Items=items,Classes=classes,ClassId=classId,Page=page,TotalPages=Math.Max(1,(int)Math.Ceiling(total/(double)pageSize))};} }
